import sqlite3
import json
import re

def parse_hours_and_check_late_night(hours_str):
    """
    Parse the hours string and check if any day closes after 10 PM.
    Hours format example: '{"Monday":"10:00-18:00","Tuesday":"10:00-18:00",...}'
    """
    if not hours_str:
        return False
    try:
        hours_dict = json.loads(hours_str.replace("'", "\""))
    except json.JSONDecodeError:
        return False

    for day, time_range in hours_dict.items():
        if time_range == "Closed":
            continue
        if '-' not in time_range:
            continue
        open_time, close_time = time_range.split('-')
        # Handle cases like '10:00-2:00' which means next day
        if len(close_time.split(':')) == 2:
            hour, minute = map(int, close_time.split(':'))
            if hour > 22 or (hour == 22 and minute > 0) or hour < 6:
                return True
    return False

# Database path configuration
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
}

try:
    # Connect to the business database
    conn = sqlite3.connect(sqlite_paths["business"])
    cursor = conn.cursor()

    # Query businesses that are open
    cursor.execute("SELECT business_id, name, address, city, state, hours FROM business WHERE is_open = 1")
    rows = cursor.fetchall()

    # Filter businesses that are open after 10 PM
    late_night_businesses = []
    for row in rows:
        business_id, name, address, city, state, hours = row
        if parse_hours_and_check_late_night(hours):
            late_night_businesses.append({
                "business_id": business_id,
                "name": name,
                "address": address,
                "city": city,
                "state": state
            })

    # Output results
    print(f"Found {len(late_night_businesses)} businesses open after 10 PM:")
    for business in late_night_businesses[:10]:  # Show first 10 results
        print(f"- {business['name']} ({business['address']}, {business['city']}, {business['state']})")

except sqlite3.Error as e:
    print(f"SQLite error: {e}")
except Exception as e:
    print(f"Error: {e}")
finally:
    if 'conn' in locals():
        conn.close()
